-- ============================================================================
-- ALUMNI TRACER PORTAL — FULL SUPABASE POSTGRES MIGRATION (SCHEMA + DATA + RLS)
-- Target Project: vvivqnuewakbfrkhxloz (https://vvivqnuewakbfrkhxloz.supabase.co)
-- ============================================================================
-- Best Practices Applied:
-- 1. SQL-standard `bigint generated by default as identity` primary keys
-- 2. Timezone-aware `timestamptz` timestamps & automatic `updated_at` triggers
-- 3. Explicit indexes on all foreign keys and frequently filtered columns
-- 4. Row Level Security (RLS) enabled on every table in `public`
-- 5. RLS policies use `TO authenticated`, `(select auth.uid())`, and
--    `app_metadata` (never `user_metadata` or deprecated `auth.role()`)
-- ============================================================================

BEGIN;

-- ── 1. Helper Trigger Function for Updated_At / updated_at ──────────────────
CREATE OR REPLACE FUNCTION public.set_current_timestamp_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.set_current_timestamp_pascal_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
BEGIN
  NEW."Updated_At" = NOW();
  RETURN NEW;
END;
$$;

-- ── 2. Core Tables (Topological Order) ──────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.campuses (
  "Campus_ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "School_Name" text NOT NULL,
  "Abbreviation" text NOT NULL,
  "Campus" text NOT NULL,
  "Address" text NOT NULL,
  "Alumni_Head_Email" text UNIQUE,
  "Created_At" timestamptz NOT NULL DEFAULT NOW(),
  "Updated_At" timestamptz NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.colleges (
  "College_ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Campus_ID" bigint NOT NULL REFERENCES public.campuses("Campus_ID") ON DELETE CASCADE ON UPDATE CASCADE,
  "College_Name" text NOT NULL,
  "Abbreviation" text NOT NULL,
  "Created_At" timestamptz NOT NULL DEFAULT NOW(),
  "Updated_At" timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS colleges_campus_id_idx ON public.colleges ("Campus_ID");

CREATE TABLE IF NOT EXISTS public.departments (
  "Department_ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Campus_ID" bigint NOT NULL REFERENCES public.campuses("Campus_ID") ON DELETE CASCADE ON UPDATE CASCADE,
  "College_ID" bigint NOT NULL REFERENCES public.colleges("College_ID") ON DELETE CASCADE ON UPDATE CASCADE,
  "Department_Name" text NOT NULL,
  "Abbreviation" text NOT NULL,
  "Coordinator_Name" text,
  "Created_At" timestamptz NOT NULL DEFAULT NOW(),
  "Updated_At" timestamptz NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_department UNIQUE ("College_ID", "Department_Name")
);
CREATE INDEX IF NOT EXISTS departments_campus_id_idx ON public.departments ("Campus_ID");
CREATE INDEX IF NOT EXISTS departments_college_id_idx ON public.departments ("College_ID");

CREATE TABLE IF NOT EXISTS public.alumni (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  alumni_id text UNIQUE,
  "FirstName" text NOT NULL,
  "LastName" text NOT NULL,
  "Email" text UNIQUE,
  "GraduationYear" integer NOT NULL,
  "College_ID" bigint REFERENCES public.colleges("College_ID") ON UPDATE CASCADE,
  "Status" text DEFAULT 'pending' CHECK ("Status" IN ('active', 'pending', 'inactive', 'incomplete')),
  "Department_ID" bigint REFERENCES public.departments("Department_ID") ON UPDATE CASCADE,
  created_at timestamptz NOT NULL DEFAULT NOW(),
  updated_at timestamptz NOT NULL DEFAULT NOW(),
  "Province" text,
  "Municipality" text,
  "Barangay" text,
  "Contact_Number" text
);
CREATE INDEX IF NOT EXISTS alumni_graduation_year_idx ON public.alumni ("GraduationYear");
CREATE INDEX IF NOT EXISTS alumni_status_idx ON public.alumni ("Status");
CREATE INDEX IF NOT EXISTS alumni_college_id_idx ON public.alumni ("College_ID");
CREATE INDEX IF NOT EXISTS alumni_department_id_idx ON public.alumni ("Department_ID");
CREATE INDEX IF NOT EXISTS alumni_lower_email_idx ON public.alumni (LOWER("Email"));

CREATE TABLE IF NOT EXISTS public.user_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "First_Name" text,
  "Last_Name" text,
  "Role" text DEFAULT 'Head_Admin',
  "Email" text UNIQUE,
  "College" text,
  "Department" text,
  "Campus" bigint,
  account_id text REFERENCES public.alumni(alumni_id) ON DELETE SET NULL ON UPDATE CASCADE,
  "Password" text
);
CREATE INDEX IF NOT EXISTS user_accounts_account_id_idx ON public.user_accounts (account_id);
CREATE INDEX IF NOT EXISTS user_accounts_role_idx ON public.user_accounts ("Role");
CREATE INDEX IF NOT EXISTS user_accounts_campus_idx ON public.user_accounts ("Campus");

CREATE TABLE IF NOT EXISTS public.staffs (
  "Staff_ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Campus_ID" bigint NOT NULL REFERENCES public.campuses("Campus_ID") ON UPDATE CASCADE,
  "College_ID" bigint REFERENCES public.colleges("College_ID") ON DELETE SET NULL ON UPDATE CASCADE,
  "Department_ID" bigint REFERENCES public.departments("Department_ID") ON DELETE SET NULL ON UPDATE CASCADE,
  "First_Name" text NOT NULL,
  "Middle_Name" text,
  "Last_Name" text NOT NULL,
  "Email" text NOT NULL UNIQUE,
  "Contact_Number" text,
  "Position" text NOT NULL,
  "Role" text NOT NULL CHECK ("Role" IN ('Developer', 'Head Admin', 'Coordinator', 'Department Staff')),
  "Status" text DEFAULT 'Active' CHECK ("Status" IN ('Active', 'Inactive')),
  "Created_At" timestamptz NOT NULL DEFAULT NOW(),
  "Updated_At" timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS staffs_campus_id_idx ON public.staffs ("Campus_ID");
CREATE INDEX IF NOT EXISTS staffs_college_id_idx ON public.staffs ("College_ID");
CREATE INDEX IF NOT EXISTS staffs_department_id_idx ON public.staffs ("Department_ID");

CREATE TABLE IF NOT EXISTS public.alumni_batches (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GraduationYear" integer NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.alumni_batch_departments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GraduationYear" integer NOT NULL,
  "College_ID" bigint NOT NULL,
  "Department_ID" bigint NOT NULL,
  created_at timestamptz DEFAULT NOW(),
  CONSTRAINT unique_batch_department UNIQUE ("GraduationYear", "Department_ID")
);
CREATE INDEX IF NOT EXISTS alumni_batch_departments_college_id_idx ON public.alumni_batch_departments ("College_ID");
CREATE INDEX IF NOT EXISTS alumni_batch_departments_department_id_idx ON public.alumni_batch_departments ("Department_ID");

CREATE TABLE IF NOT EXISTS public.alumni_files (
  "File_ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Alumni_ID" bigint NOT NULL REFERENCES public.alumni(id) ON DELETE CASCADE ON UPDATE CASCADE,
  "File_Type" text NOT NULL CHECK ("File_Type" IN ('profile_picture', 'employment_proof', 'alumni_id_photo')),
  "Original_Name" text,
  "Stored_Name" text NOT NULL,
  "File_Path" text NOT NULL,
  "Mime_Type" text,
  "File_Size" integer,
  "Uploaded_At" timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS alumni_files_alumni_id_idx ON public.alumni_files ("Alumni_ID");

CREATE TABLE IF NOT EXISTS public.surveys (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL,
  description text,
  created_at timestamptz NOT NULL DEFAULT NOW(),
  status text DEFAULT 'open',
  allow_multiple_responses boolean NOT NULL DEFAULT false,
  current_batch integer DEFAULT 1,
  open_datetime timestamptz,
  close_datetime timestamptz,
  survey_state text
);

CREATE TABLE IF NOT EXISTS public.categories (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  survey_id bigint NOT NULL REFERENCES public.surveys(id) ON DELETE CASCADE,
  category_name text NOT NULL,
  description text,
  order_number integer DEFAULT 1
);
CREATE INDEX IF NOT EXISTS categories_survey_id_idx ON public.categories (survey_id);

CREATE TABLE IF NOT EXISTS public.questions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  question_text text NOT NULL,
  question_type text NOT NULL CHECK (question_type IN ('text', 'multiple_choice', 'rating', 'image')),
  analytics_key text,
  category_id bigint NOT NULL REFERENCES public.categories(id) ON DELETE CASCADE,
  required boolean NOT NULL DEFAULT false,
  question_order integer NOT NULL DEFAULT 1,
  rating_min smallint,
  rating_max smallint,
  rating_min_label text,
  rating_max_label text
);
CREATE INDEX IF NOT EXISTS questions_category_id_idx ON public.questions (category_id);

CREATE TABLE IF NOT EXISTS public.choices (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  question_id bigint NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,
  choice_text text NOT NULL
);
CREATE INDEX IF NOT EXISTS choices_question_id_idx ON public.choices (question_id);

CREATE TABLE IF NOT EXISTS public.question_logic (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  question_id bigint NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,
  choice_id bigint NOT NULL REFERENCES public.choices(id) ON DELETE CASCADE,
  action text NOT NULL DEFAULT 'next_section' CHECK (action IN ('next_section', 'go_to_section', 'submit')),
  target_category_id bigint REFERENCES public.categories(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS question_logic_question_id_idx ON public.question_logic (question_id);
CREATE INDEX IF NOT EXISTS question_logic_choice_id_idx ON public.question_logic (choice_id);
CREATE INDEX IF NOT EXISTS question_logic_target_category_id_idx ON public.question_logic (target_category_id);

CREATE TABLE IF NOT EXISTS public.responses (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  survey_id bigint NOT NULL REFERENCES public.surveys(id) ON DELETE CASCADE,
  user_email text,
  submitted_at timestamptz NOT NULL DEFAULT NOW(),
  survey_number integer,
  user_name text,
  user_id text REFERENCES public.user_accounts(account_id) ON DELETE SET NULL ON UPDATE CASCADE,
  review_status text NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending', 'reviewed', 'needs_revision')),
  CONSTRAINT unique_response_per_batch UNIQUE (survey_id, survey_number, user_email)
);
CREATE INDEX IF NOT EXISTS responses_survey_id_idx ON public.responses (survey_id);
CREATE INDEX IF NOT EXISTS responses_user_id_idx ON public.responses (user_id);
CREATE INDEX IF NOT EXISTS responses_user_email_idx ON public.responses (user_email);

CREATE TABLE IF NOT EXISTS public.answers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  response_id bigint NOT NULL REFERENCES public.responses(id) ON DELETE CASCADE,
  question_id bigint NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,
  choice_id bigint REFERENCES public.choices(id) ON DELETE SET NULL,
  answer_text text,
  answer_image_path text
);
CREATE INDEX IF NOT EXISTS answers_response_id_idx ON public.answers (response_id);
CREATE INDEX IF NOT EXISTS answers_question_id_idx ON public.answers (question_id);
CREATE INDEX IF NOT EXISTS answers_choice_id_idx ON public.answers (choice_id);

CREATE TABLE IF NOT EXISTS public.response_reviews (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  response_id bigint NOT NULL REFERENCES public.responses(id) ON DELETE CASCADE,
  reviewer_id bigint NOT NULL REFERENCES public.staffs("Staff_ID"),
  review_status text NOT NULL CHECK (review_status IN ('reviewed', 'needs_revision')),
  review_comment text,
  reviewed_at timestamptz DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS response_reviews_response_id_idx ON public.response_reviews (response_id);
CREATE INDEX IF NOT EXISTS response_reviews_reviewer_id_idx ON public.response_reviews (reviewer_id);

CREATE TABLE IF NOT EXISTS public.events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" text,
  "Date" date,
  time time,
  "Location" text,
  "Status" text DEFAULT 'Active'
);
CREATE INDEX IF NOT EXISTS events_date_time_idx ON public.events ("Date", time);

CREATE TABLE IF NOT EXISTS public.news_posts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL,
  content text NOT NULL,
  link_url text,
  image_path text,
  author_name text NOT NULL,
  author_role text,
  created_at timestamptz NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.payment_purposes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT NOW(),
  updated_at timestamptz NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  transaction_ref text NOT NULL UNIQUE,
  alumni_id bigint,
  student_number text,
  payer_name text NOT NULL,
  payer_email text,
  payer_contact text,
  campus_id bigint,
  college_id bigint,
  payment_type text NOT NULL DEFAULT 'alumni_id' CHECK (payment_type IN ('alumni_id', 'event_fee', 'membership', 'graduation_fee', 'donation', 'document_cert', 'other')),
  payment_purpose_id bigint NOT NULL REFERENCES public.payment_purposes(id),
  description text,
  amount numeric(10,2) NOT NULL DEFAULT 0.00,
  payment_method text NOT NULL DEFAULT 'cash' CHECK (payment_method IN ('cash', 'gcash', 'maya', 'bank_transfer', 'online_portal', 'over_the_counter')),
  channel_reference text,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected', 'refunded')),
  proof_file text,
  submitted_by_role text DEFAULT 'alumni',
  coordinator_id bigint,
  notes text,
  verified_by bigint,
  verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT NOW(),
  updated_at timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS payments_status_idx ON public.payments (status);
CREATE INDEX IF NOT EXISTS payments_payment_type_idx ON public.payments (payment_type);
CREATE INDEX IF NOT EXISTS payments_college_id_idx ON public.payments (college_id);
CREATE INDEX IF NOT EXISTS payments_campus_id_idx ON public.payments (campus_id);
CREATE INDEX IF NOT EXISTS payments_created_at_idx ON public.payments (created_at);
CREATE INDEX IF NOT EXISTS payments_payment_purpose_id_idx ON public.payments (payment_purpose_id);

CREATE TABLE IF NOT EXISTS public.activities (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  user_type text DEFAULT 'staff',
  action text NOT NULL,
  category text NOT NULL,
  description text,
  details jsonb,
  ip_address text,
  user_agent text,
  created_date date,
  created_time time,
  created_at timestamptz NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS activities_user_id_idx ON public.activities (user_id);
CREATE INDEX IF NOT EXISTS activities_category_idx ON public.activities (category);
CREATE INDEX IF NOT EXISTS activities_user_type_idx ON public.activities (user_type);
CREATE INDEX IF NOT EXISTS activities_created_at_idx ON public.activities (created_at);

-- ── 3. Updated_At Triggers ──────────────────────────────────────────────────
DROP TRIGGER IF EXISTS trg_campuses_updated_at ON public.campuses;
CREATE TRIGGER trg_campuses_updated_at BEFORE UPDATE ON public.campuses FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_pascal_updated_at();

DROP TRIGGER IF EXISTS trg_colleges_updated_at ON public.colleges;
CREATE TRIGGER trg_colleges_updated_at BEFORE UPDATE ON public.colleges FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_pascal_updated_at();

DROP TRIGGER IF EXISTS trg_departments_updated_at ON public.departments;
CREATE TRIGGER trg_departments_updated_at BEFORE UPDATE ON public.departments FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_pascal_updated_at();

DROP TRIGGER IF EXISTS trg_staffs_updated_at ON public.staffs;
CREATE TRIGGER trg_staffs_updated_at BEFORE UPDATE ON public.staffs FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_pascal_updated_at();

DROP TRIGGER IF EXISTS trg_alumni_updated_at ON public.alumni;
CREATE TRIGGER trg_alumni_updated_at BEFORE UPDATE ON public.alumni FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_updated_at();

DROP TRIGGER IF EXISTS trg_payment_purposes_updated_at ON public.payment_purposes;
CREATE TRIGGER trg_payment_purposes_updated_at BEFORE UPDATE ON public.payment_purposes FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_updated_at();

DROP TRIGGER IF EXISTS trg_payments_updated_at ON public.payments;
CREATE TRIGGER trg_payments_updated_at BEFORE UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.set_current_timestamp_updated_at();

