-- ── 5. Row Level Security (RLS) & Policies ──────────────────────────────────
-- Enable RLS on all exposed tables in `public`
ALTER TABLE public.campuses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.colleges ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alumni ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staffs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alumni_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alumni_batch_departments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.alumni_files ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.surveys ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.choices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.question_logic ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.responses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.response_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.news_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_purposes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;

-- Public Reference Tables (Campuses, Colleges, Departments, Events, News, Surveys)
DROP POLICY IF EXISTS "campuses_select_authenticated" ON public.campuses;
CREATE POLICY "campuses_select_authenticated" ON public.campuses
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "colleges_select_authenticated" ON public.colleges;
CREATE POLICY "colleges_select_authenticated" ON public.colleges
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "departments_select_authenticated" ON public.departments;
CREATE POLICY "departments_select_authenticated" ON public.departments
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "events_select_authenticated" ON public.events;
CREATE POLICY "events_select_authenticated" ON public.events
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "news_posts_select_authenticated" ON public.news_posts;
CREATE POLICY "news_posts_select_authenticated" ON public.news_posts
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "surveys_select_authenticated" ON public.surveys;
CREATE POLICY "surveys_select_authenticated" ON public.surveys
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "categories_select_authenticated" ON public.categories;
CREATE POLICY "categories_select_authenticated" ON public.categories
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "questions_select_authenticated" ON public.questions;
CREATE POLICY "questions_select_authenticated" ON public.questions
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "choices_select_authenticated" ON public.choices;
