  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "question_logic_select_authenticated" ON public.question_logic;
CREATE POLICY "question_logic_select_authenticated" ON public.question_logic
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

DROP POLICY IF EXISTS "payment_purposes_select_authenticated" ON public.payment_purposes;
CREATE POLICY "payment_purposes_select_authenticated" ON public.payment_purposes
  FOR SELECT TO authenticated USING ( (select auth.uid()) IS NOT NULL );

-- Alumni Records: Alumni can read/update their own record; Staff/Coordinator/Developer can read/manage
DROP POLICY IF EXISTS "alumni_select_own_or_staff" ON public.alumni;
CREATE POLICY "alumni_select_own_or_staff" ON public.alumni
  FOR SELECT TO authenticated
  USING (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'coordinator', 'developer', 'system_admin')
  );

DROP POLICY IF EXISTS "alumni_update_own_or_staff" ON public.alumni;
CREATE POLICY "alumni_update_own_or_staff" ON public.alumni
  FOR UPDATE TO authenticated
  USING (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'developer', 'system_admin')
  )
  WITH CHECK (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'developer', 'system_admin')
  );

-- User Accounts: Users can read their own row; Staff/Developer can manage
DROP POLICY IF EXISTS "user_accounts_select_own_or_admin" ON public.user_accounts;
CREATE POLICY "user_accounts_select_own_or_admin" ON public.user_accounts
  FOR SELECT TO authenticated
  USING (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'coordinator', 'developer', 'system_admin')
  );

DROP POLICY IF EXISTS "user_accounts_update_own_or_admin" ON public.user_accounts;
CREATE POLICY "user_accounts_update_own_or_admin" ON public.user_accounts
  FOR UPDATE TO authenticated
  USING (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'developer', 'system_admin')
  )
  WITH CHECK (
    LOWER("Email") = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'developer', 'system_admin')
  );

-- Survey Responses: Alumni can read/insert their own responses; Staff/Coordinator can read/review
DROP POLICY IF EXISTS "responses_select_own_or_staff" ON public.responses;
CREATE POLICY "responses_select_own_or_staff" ON public.responses
  FOR SELECT TO authenticated
  USING (
    LOWER(user_email) = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'coordinator', 'developer', 'system_admin')
  );

DROP POLICY IF EXISTS "responses_insert_own" ON public.responses;
CREATE POLICY "responses_insert_own" ON public.responses
  FOR INSERT TO authenticated
  WITH CHECK (
    LOWER(user_email) = LOWER((select auth.jwt() ->> 'email'))
  );

-- Payments: Alumni can read their own payments; Staff/Coordinator can read/manage
DROP POLICY IF EXISTS "payments_select_own_or_staff" ON public.payments;
CREATE POLICY "payments_select_own_or_staff" ON public.payments
  FOR SELECT TO authenticated
  USING (
    LOWER(payer_email) = LOWER((select auth.jwt() ->> 'email'))
    OR (select auth.jwt() -> 'app_metadata' ->> 'role') IN ('head_admin', 'staff', 'coordinator', 'developer', 'system_admin')
  );

COMMIT;